def get_bytes():
    return zlib.decompress(base64.b85decode(_B85.strip()))
def extract_to(target: Path) -> bool:
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        data = get_bytes()
        need_write = not target.is_file() or target.stat().st_size != len(data)
        if not need_write:
            need_write = hashlib.sha256(target.read_bytes()).digest() != hashlib.sha256(data).digest()
        if need_write:
            target.write_bytes(data)
        return True
    except Exception:
        return False
